import React from 'react';
import './Navbar.css';
import avootaLogo from '../assets/avootalogo.png';
import bellIcon from '../assets/icons/bell.png';
import logoutIcon from '../assets/icons/logout.png';
import userIcon from '../assets/icons/user.png'; // or replace with real user image

interface NavbarProps {
  onSearch: (query: string) => void;
}

const Navbar: React.FC<NavbarProps> = ({ onSearch }) => {
  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    onSearch(event.target.value);
  };

  return (
    <div className="navbar">
      {/* Logo */}
      <div className="logo-container">
        <img src={avootaLogo} alt="avoota logo" className="avoota-logo" />
      </div>

      {/* Search Bar */}
      <div className="search-bar">
        <span className="search-icon">🔍</span>
        <input
          type="text"
          placeholder="Search"
          onChange={handleSearchChange}
          aria-label="Search"
        />
      </div>

      {/* Right Side Icons */}
      <div className="nav-icons">
        <img src={bellIcon} alt="Notifications" className="nav-icon" />
        <img src={logoutIcon} alt="Logout" className="nav-icon" />
        <img src={userIcon} alt="User Profile" className="user-avatar" />
      </div>
    </div>
  );
};

export default Navbar;
